insert into public.publications (id, year, month, kind, grade, t, te, a, v, ve, vol, pages, doi, kci, dbpia, isbn, abs, langs) values
('2026-poly-convivialism', 2026, 8, 'article', 'KCI 등재', '다공존주의(Poly-convivialism): 이주민 지역 정주를 위한 새로운 통합이념의 모색', 'Poly-Convivialism: Toward a New Integration Ideology for the Local Settlement of Migrants', array['이용승']::text[], '민족연구', 'Minjok Yeonku', '88', '226–254', '10.35431/minjok.88.8', 'ART003376140', null, null, '한국 이민정책 20년의 성찰에서 출발하여, 이주민의 지역 정주를 위한 새로운 통합이념으로 ‘다공존주의’(poly-convivialism)를 제안한다. 다공존주의는 동화주의·다문화주의·상호문화주의와 경쟁하는 또 하나의 이념이 아니라, 이주민의 법적 지위와 생활 조건에 따라, 그리고 국가·지역·도시·마을·초국적 스케일에 따라 이들을 선택적으로 동원하는 지붕개념이자 2차 규범이다. 선택이 자의적 통치로 전유되지 않도록 최소공존조건의 사전적 우선성, 당사자 협상력의 보전, 비본질화원칙의 준수, 다중공존을 향한 이행 가능성이라는 네 가지 판별 기준을 함께 제시한다.', array['ko']::text[]),
('2026-relational-citizenship', 2026, 6, 'article', 'KCI 등재', '이주민의 ‘관계적 시민권’과 지역적 삶', 'Migrants’ ‘Relational Citizenship’ and Local Life', array['이용승','이은정']::text[], '시민과 세계', 'Citizen & the World', '48', '1–39', '10.35548/cw.2026.06.48.1', 'ART003352752', null, null, '국적 중심의 시민권 논의가 한국 사회에서 살아가는 이주민의 일상적 시민됨을 포착하지 못한다는 문제의식에서 출발한다. 시민권을 고정된 법적 지위가 아니라 여러 조건이 함께 만들어 내는 동적 구성체로 재정의하면서 ‘관계적 시민권’ 개념을 행위, 매개, 배치, 스케일, 정당화 규칙, 절단점과 수선 전략이라는 여섯 가지 하위 구성요소로 정식화하였다. 대구·경북 지역 이주민 9명에 대한 심층 인터뷰를 토대로, 이들이 비자·휴대전화 본인인증·통번역·온라인 커뮤니티·비공식 노동 네트워크의 결합망 속에서 이미 시민으로 행위하고 있음을 보였다.', array['ko']::text[]),
('2025-fake-news', 2025, 12, 'article', 'KCI 등재', '가짜뉴스는 어떻게 확산되는가? : ‘외국인 건보 먹튀’ 사례에 대한 ANT 분석', 'How Does Fake News Spread? An ANT Analysis of the ‘Foreigners’ Health Insurance Free-Riding’ Case', array['이용승']::text[], '다문화콘텐츠연구', 'Journal of Multi-Cultural Contents Studies', '54', '289–327', '10.15400/mccs.2025.12.54.09', 'ART003291327', null, null, '이주민들을 배제하고 소외시키는 가짜뉴스가 어떻게 확산하고 자리를 잡는지, 그 복잡한 경로와 메커니즘을 추적한다. 이미 대중의 인식 속에 자명한 사실로 자리 잡은 ‘외국인 건보먹튀’를 사례로 삼아, “이주민에 관한 가짜뉴스는 어떻게 수많은 행위자를 성공적으로 등록(enrol)시켜 의심할 여지 없는 사실로 자리 잡게 되었는가?”를 묻는다. 행위자는 인간뿐 아니라 기술, 플랫폼, 담론 등의 비인간 행위자를 포함하며, 가짜뉴스는 정보의 오류가 아니라 인간과 비인간 행위자가 얽힌 사회적·기술적·정치적 현상임을 주장한다.', array['ko']::text[]),
('2024-us-local-immigration', 2024, 9, 'article', 'KCI 등재', '미국 지방정부의 이민정책과 그 함의: 캘리포니아와 샌프란시스코를 중심으로', 'Immigration Policies and Implications of State and Local Government in the U.S.: Focusing on California and San Francisco', array['이용승']::text[], '민족연구', 'Minjok Yeonku', '84', '12–39', '10.35431/minjok.84.2', 'ART003113032', null, null, '미국을 사례로 주(state) 및 시 정부의 이민정책을 살펴보고, 그것이 한국 지방정부의 이민정책에 줄 수 있는 함의를 도출한다. 캘리포니아 주정부와 샌프란시스코시를 사례로, 지역 정부가 독자적인 이민정책을 수립·실천할 수 있는 요인으로 지방의 이민정책 수요 확대와 정책 환경 변화를 제시하였다. 함의로 이주민 통합이라는 목표 설정, 지자체 역량 함양과 거버넌스 구축, 이주민의 시민적 참여 방안, 피난처 정책, 자격증 인정 등을 제안한다.', array['ko']::text[]),
('2024-study-abroad-capital', 2024, 6, 'article', 'KCI 등재', '유학 관련 자본의 경합과 경쟁', 'Competition and Struggle over Study-Abroad-Related Capital', array['이용승','이화숙']::text[], '디아스포라연구', 'Diaspora Studies', '18(1)', '233–271', null, 'ART003087522', null, null, '한국의 대학에서 사회과학·인문학 전공자들이 학위를 받고 귀국한 뒤, 전공지식과 학위를 자본으로 어떤 직업을 갖게 되는가를 묻는다. 귀국한 유학생들이 전공과 무관하게 한국어 교육 분야에 종사하는 사례가 많다는 관찰에서 출발하여, 일자리를 찾는 과정에서 경험하는 전공지식과 한국어 능력 간의 경합, 그리고 한국어 능력과의 관련 하에서 직업을 얻는 과정을 추적한다.', array['ko']::text[]),
('2023-suffrage', 2023, 6, 'article', 'KCI 등재', '이주민의 참정권 논쟁과 다문화 민주주의의 모색', 'Controversy over Suffrage of Immigrants and the Search for Multicultural Democracy', array['이용승','심승우']::text[], '시민사회와 NGO', 'Civil Society & NGO', '21(1)', '263–297', null, 'ART002965844', null, null, '한국에서 이주민의 참정권을 중심으로 다양한 정치사회적 쟁점을 살펴보고, 민주주의의 관점에서 참정권의 발전 방향을 모색한다. 참정권에 반대하는 논리와 그 정치적·이념적 배경을 비판적으로 검토하고, 인권 규범의 관점에서 참정권의 정치철학적 함의를 재검토한다. 결론적으로 다문화 민주주의의 관점에서 이주민 참정권에 대한 전향적 모색, 주민권의 적극적 도입, 다문화 사회통합의 주체와 이민청의 역할 등을 제안하였다.', array['ko']::text[]),
('2022-cultural-rights', 2022, 12, 'article', '일반논문', '언어장벽과 이주배경 주민의 문화권', 'Language Barriers and the Cultural Rights of Migrants', array['이용승']::text[], '한국이민학', 'Korean Journal of Immigration Studies', '9(2)', '79–97', null, null, 'NODE11342752', null, '한국 사회에서 이주배경 주민의 문화권을 고찰하며, 특히 언어와 문화권의 관계에 주목한다. 문화권은 소수자를 포함한 모든 사회 구성원의 문화적 ‘권리’에 초점을 둔다. 이주배경 주민의 문화권은 첫째 자신의 문화를 편견 없이 드러내고 향유할 권리, 둘째 주류 문화에 차별 없이 접근하고 향유할 권리로 나뉜다. 문화적 권리의 확대를 위해 ‘다문화 공간’ 기획과 한국어 교육의 관점 변화를 구체적 제안으로 제시한다.', array['ko']::text[]),
('2022-affective-factors', 2022, 3, 'article', 'KCI 등재', '유학생의 학업 수행과 관련한 정의적 요인 연구의 동향 분석: 유학생 교육정책의 함의 모색을 위하여', 'Trend Analysis of Research on Affective Factors in International Students’ Academic Performance', array['이윤주','이화숙','이용승']::text[], '인문과학연구', 'Humanities Studies', '72', '319–361', null, 'ART002829655', null, null, '유학생의 학업 수행과 관련 있는 정의적 요인에 관한 연구 동향을 분석하여 교육적 함의를 모색한다. 학술지 논문 137편을 체계적 문헌 고찰의 방법으로 분석하였다. 연구는 2009년 ‘불안’과 ‘태도’ 연구에서 시작되었고, 2016년에서 2021년 3월 사이에 74%가 발표되었다. 전체의 약 84%가 양적 연구였으나 후반기에는 혼합 연구가 확대되고 있다.', array['ko']::text[]),
('2022-refugee-family', 2022, 3, 'article', 'KCI 등재', '어느 난민 가족의 한국살이: ‘권리를 가질 권리’로서 성원의 자격에 대하여', 'A Refugee Family’s Life in Korea: Regarding the Qualifications for Members as a “Right to Have Rights”', array['이용승','이은정']::text[], '민족연구', 'Minjok Yeonku', '79', '92–116', '10.35431/minjok.79.4', 'ART002815969', null, null, '‘이미’ 난민이지만 ‘아직’ 난민은 아닌 어느 가족의 한국살이를 들여다보고, 이를 근거로 ‘성원의 자격’을 고민한다. 난민이 처한 어려움을 전시하고 어떤 정책이 필요한지를 설파하는 학술적 관성을 넘어서기 위한 방안으로 공동체 성원으로서의 권리인 ‘성원권’(membership)에 주목하였다. 한나 아렌트가 말한 정치 공동체에 속할 자격으로서 ‘권리를 가질 권리’를 논의의 축으로 삼는다.', array['ko']::text[]),
('2021-covid-intl-students', 2021, 5, 'article', 'KCI 등재', 'COVID-19 팬데믹이 유학생의 취약성에 미치는 영향', 'The Impact of the COVID-19 Pandemic on the Vulnerability of International Students', array['이화숙','김정숙','이용승']::text[], '현대사회와 다문화', 'Contemporary Society and Multiculture', '11(2)', '1–34', '10.35281/cms.2021.05.11.2.1', 'ART002718902', null, null, '코로나19 팬데믹이 국내에 거주하는 유학생의 취약성에 미치는 영향을 조사한다. 재난 언어차별주의와 언어이데올로기의 이론적 개념에 근거하여, 팬데믹이 언어소수자인 유학생들에게 어떤 경험을 낳았는지 분석하였다.', array['ko']::text[]),
('2021-nation-nationalism', 2021, 3, 'article', 'KCI 등재', '이음체의 관점에 기초한 민족과 민족주의의 한국적 재구성', 'Reconceptualization of Nation and Nationalism in the Korean Context Based on the View of Seriality', array['이용승']::text[], '국제정치연구', 'The Journal of International Relations', '24(1)', '31–57', '10.15235/jir.2021.03.24.1.31', 'ART002704650', null, null, '한국적 맥락에서 민족과 민족주의를 재사유하기 위해 기획되었다. 2018년 평창올림픽 남북 단일팀 구성을 둘러싼 사회적 논란은 민족과 민족주의에 대한 새로운 사유의 필요를 요청한다. 젊은 층을 중심으로 한 인식 변화와 ‘이음체’(seriality)의 관점에서 민족을 재구성한다.', array['ko']::text[]),
('2020-student-naming', 2020, 3, 'article', 'KCI 등재', '유학생 관련 명칭의 현황과 명칭 사용의 문제: 학술 논문의 제목을 중심으로', 'Current Status and Problems of Naming for International Students: Focusing on the Titles of Academic Papers', array['이화숙','이용승']::text[], '인문과학연구', 'Humanities Studies', '39', '83–108', null, 'ART002574394', null, null, null, array['ko']::text[]),
('2019-politics-violence', 2019, 9, 'article', 'KCI 등재', '정치와 폭력: 공존의 (불)가능성 모색', 'Politics and Violence: Groping for the (Im)possibility of Coexistence', array['이용승']::text[], '국제정치연구', 'The Journal of International Relations', '22(3)', '207–236', '10.15235/jir.2019.09.22.3.207', 'ART002511713', null, null, '국가와 정치에서 폭력이 차지하는 위상을 성찰하고, 그것의 전환 가능성을 모색한다. 정치에서 폭력의 위상이 상당함에도 정치학과 현실 정치는 폭력의 문제를 깊이 성찰하지 않거나 뿌리 뽑아야 할 악으로 다루어왔다. 폭력은 인간 삶에서 근원적 위치를 점유하며 정치적 삶에서도 필수 불가결한 요소이지만, 현실의 폭력을 어찌할 수 없는 것으로 치부하는 것은 온당하지 못하다.', array['ko']::text[]),
('2018-who-is-refugee', 2018, 9, 'article', '일반논문', '난민은 누구이고, 우리의 태도는 어떠해야 하는가?', 'Who Is a Refugee, and What Should Our Attitude Be?', array['이용승']::text[], '민족연구', 'Minjok Yeonku', '72', '166–183', null, 'ART002379385', null, null, null, array['ko']::text[]),
('2018-denizenship-joseonjok', 2018, 6, 'article', 'KCI 등재', '이주민의 주민권: 조선족 여성 이장 사례 연구', 'Denizenship of Migrants: A Case Study of a Korean-Chinese Female Village Head', array['이용승','이은정']::text[], '디아스포라연구', 'Diaspora Studies', '12(1)', '113–144', null, 'ART002353980', null, null, '주민권의 관점에서 농촌 지역에 정착한 결혼이주여성이 지역 사회에 안정적으로 편입·통합되는 과정을 분석한다. 유교적 전통이 강하게 작동하는 농촌사회에서 여성 이주민이 주민권을 획득하는 데 기여한 요인과 구조를 살핀다. 사례를 제공한 조선족 출신 결혼이주여성은 어려운 결혼생활에서 얻은 신뢰를 바탕으로 7년간(2010–2016) 마을 이장을 지냈다.', array['ko']::text[]),
('2018-quebec-heterotopia', 2018, 3, 'article', 'KCI 등재', '헤테로토피아로서 퀘벡: 퀘벡의 분리주의에 관한 한 해석', 'Quebec as a Heterotopia: An Interpretation of Quebec Separatism', array['이용승','김영진']::text[], '민족연구', 'Minjok Yeonku', '71', '100–125', null, 'ART002319957', null, null, '여러 민주주의 국가에서 문제가 되고 있는 분리주의 사례를 퀘벡을 통해 살펴본다. 1980년과 1995년 독립 주민투표가 부결된 이후 독립 가능성은 낮아졌지만, 퀘벡의 독립은 휘발성이 강한 만큼 언제든지 부상할 수 있는 문제다. 기존의 정치·경제적, 사회문화적 분석과 달리 공간의 관점에서 접근하여, 퀘벡을 헤테로토피아로 규정하고 혼종성과 저항공간이라는 측면에서 해석한다.', array['ko']::text[]),
('2017-diffusion', 2017, 10, 'article', '일반논문', '다문화주의의 국제적확산과 한국', 'The International Diffusion of Multiculturalism and Korea', array['이용승']::text[], '로컬리티 인문학', 'Localities', '18', '327–338', null, 'ART002279102', null, null, null, array['ko']::text[]),
('2016-thaad', 2016, 9, 'article', 'KCI 등재', '사드와 한국의 국익', 'THAAD and Korea’s National Interest', array['정욱식','이용승']::text[], '민족연구', 'Minjok Yeonku', '67', '4–26', null, 'ART002138718', null, null, '사드 배치가 결정된 이후 한반도와 동아시아의 안보환경이 빠르게 변화하고 있다. 이 글은 사드 배치 찬반을 떠나 그것이 한국의 국익에 유익할 것인가라는 질문을 던지고 여러 관점에서 조망한다. 사드가 무엇인지, 미 국방부가 진행한 사드 시험의 내력을 살펴본 뒤, 사드 배치 정당화 논리를 효용성의 측면에서 검토한다.', array['ko']::text[]),
('2016-acceptance', 2016, 6, 'article', 'KCI 등재', '다문화수용성 제고, 왜 그리고 어떻게 해야 하는가?', 'The Enhancement of Multicultural Acceptance: Why and How to Do It?', array['이용승']::text[], '현대사회와 다문화', 'Contemporary Society and Multiculture', '6(1)', '1–26', null, 'ART002132605', null, null, '다문화수용성 증대가 다문화정책 구현의 도구로서 의미가 있다는 전제 아래, ‘사실’, ‘당위’, ‘이익’, ‘옳음’의 관점에서 그 이유를 정당화하였다. 대안으로 담론과 교육, 정책을 제시하였고, 담론으로는 한국 사회의 이질성, 연구자의 역할, 반다문화주의 논쟁 활용, 주민권/구성원권, ‘다문화’라는 사람 지칭어의 폐지 등을 개진하였다. 교육 부문에서는 교육과정의 구조 변경과 다문화시민성 함양의 시민교육을, 정책으로는 정책 피로감 완화, 대상 확대, 차별금지법 제정, 차별 영향분석평가 등을 제안한다.', array['ko']::text[]),
('2016-north-korean-migrants', 2016, 6, 'article', 'KCI 등재', '북한이탈주민 통합, 어떻게 가능할 것인가?', 'How Can the Integration of North Korean Defectors Be Possible?', array['이용승']::text[], '민족연구', 'Minjok Yeonku', '66', '4–23', null, 'ART002132680', null, null, '2016년 3월 국내 체류 북한이탈주민은 2만 9,137명이다. 이 글은 북한이탈주민의 남한 사회통합 방안 모색을 위해 그들은 누구이고, 차별의 작동방식은 어떠하며, 우리 사회는 이들을 어떻게 대우하고 있는가를 묻는다. 북한이탈주민의 남한 내 위상을 태생적 이중성과 성질상의 이중성으로 규정하고 통합의 조건을 검토한다.', array['ko']::text[]),
('2016-local-integration', 2016, 3, 'article', 'KCI 등재', '이주민 지역사회통합과 주민권의 기능', 'Social Integration of Migrants in a Local Community and the Function of Denizenship', array['이용승']::text[], '민족연구', 'Minjok Yeonku', '65', '4–25', null, 'ART002132634', null, null, '주민권을 통해 이주민의 지역사회 통합방안을 제시한다. 주민권은 체류자격 내지는 법적 지위, 인종, 민족, 출신국가, 개인적 성향, 계급, 사회적 지위 등과 무관하게 단지 그/녀가 해당 지역의 주민이라는 이유만으로 마땅히 인정되어야 하는 권리와 지위, 정체성이 있다는 것을 말한다. 사회통합의 의미를 규정해 지역과 연결하고, 시민권의 내용으로부터 주민권의 내용을 구성하며 보편성·다문화주의·인권과의 관계를 통해 정당화를 시도하였다.', array['ko']::text[]),
('2016-gakushuin', 2016, null, 'article', '국제학술지', 'Multiculturalism and Anti-multiculturalism Phenomena in South Korea', 'Multiculturalism and Anti-multiculturalism Phenomena in South Korea', array['이용승']::text[], 'The Gakushuin Journal of International Studies', 'The Gakushuin Journal of International Studies', '3', '17–36', null, null, null, null, null, array['en']::text[]),
('2015-migrant-values', 2015, 6, 'article', 'KCI 등재', '이주민의 가치 연구: 필리핀 CFO 교육 이주여성을 중심으로', 'A Study on the Values of Migrants: Focusing on Filipino Women in CFO Pre-Departure Education', array['이용승']::text[], '민족연구', 'Minjok Yeonku', '62', '120–150', null, 'ART001993687', null, null, '한국으로의 이주가 최종적으로 승인·결정되어 이주의 마지막 절차를 이수하고 있는 필리핀 이주여성의 가치체계를 살펴본다. 이주민이 수용국에 입국하기 전에 가지고 있던 일상적 가치는 초기 정착과정은 물론 이후 적응 및 통합과정에서 중대한 영향을 끼친다. 이들이 어떠한 가치를 체화하고 이주 수용국으로 들어오는지를 분석한다.', array['ko']::text[]),
('2015-social-capital', 2015, 5, 'article', 'KCI 등재', '이주민 사회자본에 관한 연구: 대구·경북 이주민과의 인터뷰를 중심으로', 'A Study on the Social Capital of Migrants: Focusing on Interviews with Migrants in Daegu and Gyeongbuk', array['이용승','이은정']::text[], '오토피아', 'Oughtopia', '30(1)', '93–134', null, 'ART001993930', null, null, '이주민이 한국 사회 유입 이후 구축하게 되는 다양한 사회자본을 살펴본다. 출신국가 공동체, 시민단체, 정치조직, 노동조합 활동을 하고 있는 대구·경북 지역 이주민 6명을 심층 인터뷰하여, 연결망 참여를 통해 축적되는 사회자본의 내용과 성격, 그리고 그것이 이주민의 삶과 적응에 어떠한 기능을 하는지 분석하였다.', array['ko']::text[]),
('2015-omnes', 2015, 1, 'article', 'KCI 등재', 'Discussion on Multiculturalism in Korea: The Origin of Lack of Opposition to Multiculturalism', 'Discussion on Multiculturalism in Korea: The Origin of Lack of Opposition to Multiculturalism', array['이용승']::text[], 'OMNES: Journal of Multicultural Society', 'OMNES: Journal of Multicultural Society', '5(2)', '85–114', '10.15685/omnes.2015.01.5.2.85', 'ART001960324', null, null, null, array['en']::text[]),
('2014-citizenship-aporia', 2014, 12, 'article', 'KCI 등재', '다문화시대의 시민권 아포리아: 누가 시민이며, 시민권 향유의 주체는 누구인가?', 'Citizenship Aporia in the Age of Multiculturalism: Who Are Citizens and Who Has the Right to Enjoy Citizenship?', array['이용승']::text[], '한국정치학회보', 'Korean Political Science Review', '48(5)', '185–206', null, 'ART001953559', null, null, '시민권은 국가적 경계를 확인하고 개별 구성원들의 보편성과 보편적 권리에 기초를 두는 반면, 다문화주의는 보편성보다 특수성과 다양성에 주목하며 문화 ‘집단’으로 호명될 수 있는 사람들에게 부여될 특수하고 차별적인 권리를 옹호한다. 이 글은 양자가 필연적으로 노정할 수밖에 없는 철학적 아포리아를 정식화하고, 양자 간의 긴장을 해소하고 상보성을 도모할 방안으로 ‘구성원권’(membership)과 ‘주민권’(denizenship)에 대한 새로운 해석을 제시한다.', array['ko']::text[]),
('2014-human-security', 2014, 10, 'article', 'KCI 등재', '국제이주와 인간안보', 'International Migration and Human Security', array['이용승']::text[], '국제관계연구', 'Journal of International Relations', '19(2)', '137–169', '10.18031/jip.2014.10.19.2.137', 'ART001921285', null, null, '이주는 국제정치연구의 적절한 주제인가? 이 글은 국가안보와 인간안보의 관점에서 이주의 주요 단계 및 국면을 살펴봄으로써 이주와 국제정치연구를 연계시키고자 한다. 이주는 지구화 시대의 핵심 이슈임에도 기존 국제정치 학계는 큰 관심을 두지 않았고, 특히 한국에서는 관련 연구가 매우 드물다. 이주를 전통적 안보와 인간안보의 관점에서 분석하여 이주가 국제정치연구의 주요 대상이 될 수 있음을 주장한다.', array['ko']::text[]),
('2014-motivation', 2014, 6, 'article', 'KCI 등재', '국제 이주의 동기에 관한 연구: 필리핀 결혼이주여성의 내러티브를 중심으로', 'A Study on the Motivation for International Migration: Narratives of Filipino Marriage-Migrant Women', array['이용승']::text[], '디아스포라연구', 'Diaspora Studies', '8(1)', '119–144', null, 'ART001882354', null, null, '필리핀 결혼이주여성이 한국으로 이주하는 동기와 배경을 탐색한다. 이주해 왔거나 이주할 예정인 필리핀 여성 9명을 한국과 필리핀에서 각각 인터뷰하여 그들의 이야기(narratives)를 분석하는 질적 연구를 수행하였다. 개별 이주민의 이야기에 주목하여, 이주를 선택하는 이유가 상당히 중첩적이라는 사실을 확인한다.', array['ko']::text[]),
('2013-policy-naming', 2013, 12, 'article', 'KCI 등재', '다문화시대의 정책명칭 연구: ‘외국인정책’을 중심으로', 'A Study on Policy Naming in the Multicultural Era: Focusing on ‘Foreigner Policy’', array['이화숙','이용승']::text[], '어문학', 'Korean Language and Literature', '122', '209–233', null, 'ART001835707', null, null, null, array['ko']::text[]),
('2013-korean-education-policy', 2013, 6, 'article', 'KCI 등재', '다문화 시대의 사회통합과 한국어 교육정책: 이주민 참여율 분석을 중심으로', 'Social Integration and Korean Language Education Policy in the Multicultural Era: Focusing on Migrant Participation Rates', array['이화숙','이용승']::text[], '한국어교육', 'Journal of Korean Language Education', '24(2)', '285–316', null, 'ART001771320', null, null, null, array['ko']::text[]),
('2013-civic-integration', 2013, 6, 'article', 'KCI 등재', '한국과 서유럽의 이민자 시민통합정책 비교 연구', 'The Comparative Study on Civic Integration Policies in Korea and Western Europe', array['이용승','김용찬']::text[], '국제정치연구', 'The Journal of International Relations', '16(1)', '143–162', '10.15235/jir.2013.06.16.1.143', 'ART001777341', null, null, '이민자 통합에 실패한 서유럽은 1990년대 후반부터 ‘시민통합정책’(civic integration policies)을 시행해 왔다. 이 글은 서유럽 이민자 통합 정책의 공통 요소를 시민통합정책으로 정식화하고, 한국의 유사한 정책과 비교 분석한다. 서유럽은 ‘통합의 위기’에 직면해 시민통합정책을 도입한 반면, 한국은 이민자 급증에 대응하기 위해 도입했다는 차이를 제시하며, 시민통합정책이 주류 사회의 가치 수용을 요구하는 동화주의적 요소를 내포한다는 점에서 유사성도 발견한다.', array['ko']::text[]),
('2013-political-participation', 2013, 3, 'article', 'KCI 등재', '이주민 정치참여 영향요인에 대한 탐색적 연구: 대구·경북지역 결혼이주여성을 중심으로', 'An Exploratory Study on the Factors Influencing Migrants’ Political Participation: Focusing on Marriage-Migrant Women in Daegu and Gyeongbuk', array['이용승','이용재']::text[], '민족연구', 'Minjok Yeonku', '53', '110–129', null, 'ART001746580', null, null, null, array['ko']::text[]),
('2013-marriage-migrant-acculturation', 2013, null, 'article', '일반논문', '결혼이주여성의 문화적응: 베트남과 필리핀 이주여성을 중심으로', 'Cultural Adaptation of Marriage-Migrant Women: Focusing on Vietnamese and Filipino Women', array['이용승','이용재']::text[], '다문화와 인간', 'Multiculture & Human', '2(1)', '163–185', null, null, null, null, null, array['ko']::text[]),
('2012-integration-comparison', 2012, null, 'article', '일반논문', '이주민 통합정책 국제비교: 법과 제도를 중심으로', 'International Comparison of Migrant Integration Policies: Focusing on Law and Institutions', array['이용승']::text[], '다문화와 인간', 'Multiculture & Human', '1(2)', '199–233', null, null, null, null, null, array['ko']::text[]),
('2011-us-multicultural-education', 2011, 1, 'article', 'KCI 등재후보', '미국 다문화교육의 이론과 실제', 'Multicultural Education in the U.S.: Theory and Practice', array['이용승']::text[], '민족연구', 'Minjok Yeonku', '47', '80–100', null, null, 'NODE08846974', null, null, array['ko']::text[]),
('2011-discourse-topography', 2011, 12, 'article', 'KCI 등재후보', '한국 다문화주의의 담론지형에 관한 소고', 'A Note on the Discursive Topography of Korean Multiculturalism', array['이용승']::text[], '인문과학연구', 'Humanities Studies', '16', '133–159', null, 'ART001611786', null, null, null, array['ko']::text[]),
('2010-critical-review', 2010, null, 'article', 'KCI 등재후보', '다문화정책에 대한 비판적 검토: 주체와 제도를 중심으로', 'A Critical Review of Multicultural Policy: Focusing on Subjects and Institutions', array['이용승']::text[], '민족연구', 'Minjok Yeonku', '44', '126–144', null, null, null, null, null, array['ko']::text[]),
('2010-theory-justification', 2010, 3, 'article', 'KCI 등재', '다문화주의의 이론적 검토와 정당화', 'Theoretical Review and Justification of Multiculturalism', array['이용승']::text[], '민족연구', 'Minjok Yeonku', '41', '18–51', null, 'ART001428029', null, null, null, array['ko']::text[]),
('2004-australia', 2004, null, 'article', '일반논문', '호주의 다문화주의', 'Multiculturalism in Australia', array['이용승']::text[], '동아시아연구', 'East Asian Studies', '8', '117–205', null, null, null, null, null, array['ko','en']::text[]),
('brief-2019-local-integration', 2019, 11, 'brief', '이슈브리프', 'Local Integration Policies for Migrants in South Korea', 'Local Integration Policies for Migrants in South Korea', array['이용승']::text[], '이민정책연구원 Issue Brief', 'Migration Research & Training Centre Issue Brief', '2019-11', '', null, null, null, null, null, array['en']::text[])
insert into public.books (id, year, month, grade, t, te, a, v, ve, vol, pages, isbn, abs, langs) values
('book-2023-transnational-students', 2023, 5, '저서(공저)', '초국적 관점에서 본 유학생의 경험과 유학정책', 'International Students’ Experiences and Study-Abroad Policy from a Transnational Perspective', array['대구대학교 다문화사회정책연구소','김명광','김연희','이용승 외']::text[], '푸른길', 'Pureun-gil', '대구대학교 다문화사회정책연구소 총서 06', '360쪽', '9788962910209', '제8장 「유학생 관련 명칭의 현황과 명칭 사용의 문제」(이화숙·이용승), 제9장 「유학생의 학업 수행과 관련한 정의적 요인 연구의 동향 분석」(이윤주·이화숙·이용승) 집필.', array['ko']::text[]),
('book-2019-life-peace', 2019, null, '저서(공저)', '지구화와 이주 그리고 생명평화', 'Globalization, Migration and Life Peace', array['김수진','이용승','오현선 외']::text[], '도서출판 참', 'Cham', null, '310쪽', null, null, array['ko']::text[]),
('book-2018-civic-ethics', 2018, 2, '저서(공저)', '지구화시대 다문화와 시민윤리', 'Multiculturalism and Civic Ethics in the Age of Globalization', array['최병두','이용승','이민경']::text[], '열린길', 'Yeollin-gil', '대안문화총서 27', '344쪽', null, null, array['ko']::text[]),
('book-2017-understanding-multicultural', 2017, 3, '교재(공저)', '다문화사회의 이해: 10가지 접근', 'Understanding Multicultural Society: Ten Approaches', array['이광규','선우현','김성일','조광제','성용구','차성란','권금상','엄수영','이용승']::text[], '태영출판사', 'Taeyoung Publishing', null, '351쪽', '9788963022116', null, array['ko']::text[]),
('book-2016-critique', 2016, 6, '저서(공저)', '한국 다문화주의 비판', 'A Critique of Korean Multiculturalism', array['오문석','김주영','박휴용','김현미','박종명','이진형','김희강','주재원','이용승 외']::text[], '앨피', 'LP', '디아스포라 휴머니티즈 총서 2', '459쪽', '9791187430032', '제2장 「다문화 시대의 시민권 아포리아: 누가 시민이며, 시민권 향유의 주체는 누구인가?」 집필.', array['ko']::text[]),
('book-2016-writing', 2016, null, '교재(공저)', '사회과학명저와 창의적 글쓰기', 'Classics in Social Science and Creative Writing', array['변상출','이용승 외']::text[], '대구대학교출판부', 'Daegu University Press', null, '201쪽', null, null, array['ko']::text[])
insert into public.courses (sort, t_ko, k_ko, d_ko, t_en, k_en, d_en, t_zh, k_zh, d_zh) values
(0, '한국사회의 다문화현상 이해', '교양 · 다문화/이주', '다문화 현상을 철학적·이론적으로 살펴보고, 이주노동자·미등록 이주민·결혼이주민·동포·유학생·돌봄노동자의 삶과 권리를 다룹니다. 사례연구와 인터뷰, 지역 이민정책과 공존의 제도화를 함께 읽습니다.', 'Understanding Multicultural Phenomena in Korean Society', 'General education · Migration', 'A theoretical and philosophical introduction to multicultural phenomena, covering the lives and rights of migrant workers, undocumented migrants, marriage migrants, co-ethnics, international students and care workers, with case studies, interviews and local immigration policy.', '韩国社会多文化现象的理解', '通识 · 多文化与移民', '从哲学与理论层面考察多文化现象，讨论移工、未登记移民、婚姻移民、同胞、留学生与照护劳动者的生活与权利，并结合案例研究、访谈与地方移民政策。'),
(1, '이민법제론', '전공 · 이민법제', '이민·체류·국적·사회통합을 둘러싼 법과 제도의 구조를 검토하고, 제도가 이주민의 일상에 작동하는 방식을 다룹니다.', 'Immigration Law and Institutions', 'Major · Immigration law', 'Examines the legal and institutional architecture of immigration, residence, nationality and integration, and how it operates in migrants’ everyday lives.', '移民法制论', '专业 · 移民法制', '考察移民、居留、国籍与社会整合相关法律制度的结构，以及制度如何作用于移民的日常生活。'),
(2, '정의란 무엇인가', '교양 · 정치사상', '정의에 관한 고전과 현대 논의를 읽으며 분배·인정·참여의 문제를 질문합니다.', 'What Is Justice?', 'General education · Political thought', 'Readings in classical and contemporary debates on justice, raising questions of distribution, recognition and participation.', '何谓正义', '通识 · 政治思想', '阅读关于正义的经典与现代论述，追问分配、承认与参与的问题。'),
(3, '과학기술사회', '교양 · 과학기술과 사회', '과학기술이 개인과 사회에 미치는 영향을 살펴보고, 일상의 사물을 통해 과학기술과 사회의 상호작용을 읽습니다.', 'Science, Technology and Society', 'General education · STS', 'Explores how science and technology shape individuals and society, reading their interaction through everyday objects.', '科学技术社会', '通识 · STS', '考察科学技术对个人与社会的影响，并通过日常物品理解科学技术与社会的互动。'),
(4, '빅컨셉', '교양 · 융합', '인문·사회·자연의 큰 개념들을 가로지르며 스스로 질문을 세우는 법을 익힙니다.', 'Big Concepts', 'General education · Interdisciplinary', 'Crossing the big ideas of the humanities, social and natural sciences, students learn to pose their own questions.', '大概念', '通识 · 跨学科', '跨越人文、社会与自然科学的大概念，学习自主提出问题的能力。'),
(5, '아시아 사회의 이해', '교양 · 지역연구', '지도와 삶 사이의 아시아를 읽으며, 아시아 사회의 구성과 변화를 다룹니다.', 'Understanding Asian Societies', 'General education · Area studies', 'Reads Asia between maps and lives, examining how Asian societies are composed and transformed.', '亚洲社会的理解', '通识 · 区域研究', '在地图与生活之间阅读亚洲，讨论亚洲社会的构成与变化。');
